mapper.select:
select applet_date, user_type, count(id) as num
from b_marketing_sync_label_${apiCode}
where label_id = #{labelId}
group by applet_date, user_type

select sync_id
from b_marketing_sync_label_${apiCode}
where ${whereStr}

      and sync_id>#{syncId} 


      and sync_id>=#{minUnCompleteId} 


      and sync_id<=#{maxId} 

and is_repeat in (1,2)
and status = 1
and label_id = #{labelId}
order by sync_id asc
limit ${pageSize};
